WITH toks AS (
  SELECT p.id, trim(t) AS tok FROM patient p, regexp_split_to_table(p.diagnosis, '[,\x1d]') t WHERE p.diagnosis IS NOT NULL
), sets AS (
  SELECT id, array_agg(DISTINCT tok ORDER BY tok) AS s FROM toks GROUP BY id
), target AS (
  SELECT id FROM sets WHERE s @> ARRAY['RA'] AND s @> ARRAY['SJS'] AND cardinality(s)=2
), flags AS (
  SELECT t.id, EXISTS (SELECT 1 FROM laboratory l WHERE l.id=t.id AND l.plt>100 AND l.plt<400) AS has_normal
  FROM target t
)
SELECT count(*) FILTER (WHERE has_normal) AS ever_normal_platelet,
       count(*) FILTER (WHERE NOT has_normal) AS never_normal_platelet
FROM flags

